exec('\nfrom __future__ import annotations\nimport time, warnings, re, math\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nimport requests\nimport plotly.graph_objects as go\nimport plotly.express as px\nfrom sklearn.linear_model import Ridge\nfrom sklearn.ensemble import RandomForestRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\ndef yaml_load(path, fallback):\n    try:\n        import yaml\n        p = ROOT / path\n        if p.exists():\n            return yaml.safe_load(p.read_text(encoding="utf-8")) or fallback\n    except Exception:\n        pass\n    return fallback\n\ndef exposure_load():\n    p = ROOT / "data" / "exposure_score_table.csv"\n    if p.exists():\n        try:\n            return pd.read_csv(p).drop_duplicates("asset")\n        except Exception:\n            pass\n    return pd.DataFrame({"asset":["XME","COPX","ITA","XAR","PRNT","SOXX","SPY"],"theme":["Mining","Copper","Defense","Aerospace","AM","Semi","Market"]})\n\nmaterials_cfg = yaml_load("config/materials_universe.yml", {"materials": {}}).get("materials", {})\nindices_cfg = yaml_load("config/global_index_config.yml", {"indices": {}}).get("indices", {})\nmacro_cfg = yaml_load("config/macro_series_config.yml", {"macro_proxies": {}}).get("macro_proxies", {})\ngeo_cfg = yaml_load("config/geopolitical_keywords.yml", {"themes": {}, "default_query": "critical minerals OR rare earth"})\nexposure = exposure_load()\n\ndef first_ticker(spec):\n    if isinstance(spec, dict):\n        if "ticker" in spec: return spec["ticker"]\n        if "tickers" in spec and spec["tickers"]: return spec["tickers"][0]\n    return str(spec)\n\ndef all_candidate_tickers_for_materials(materials):\n    out = []\n    for name, spec in materials.items():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        for t in ticks:\n            if t: out.append(t)\n    return out\n\ndef flatten_indices(idx):\n    rows = []\n    for region, mp in idx.items():\n        if isinstance(mp, dict):\n            for name, ticker in mp.items():\n                rows.append({"region":region, "name":name, "ticker":ticker})\n    return pd.DataFrame(rows)\n\ndef safe_period(interval, period):\n    if interval == "1m": return period if period in ["1d","5d"] else "5d"\n    if interval in ["2m","5m","15m","30m","60m","90m"]: return period if period in ["1d","5d","1mo"] else "1mo"\n    return period\n\n@st.cache_data(ttl=30, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers: return pd.DataFrame()\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty: return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        prices = raw["Close"].copy() if "Close" in raw.columns.get_level_values(0) else raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        prices = raw[["Close"]].copy()\n        if len(tickers) == 1: prices.columns = tickers\n    return prices.dropna(axis=1, how="all").ffill().dropna(how="all")\n\ndef resolve_material_tickers(prices, materials):\n    resolved = {}\n    rows = []\n    for name, spec in materials.items():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        selected = next((t for t in ticks if t in prices.columns), None)\n        if selected:\n            resolved[name] = selected\n        rows.append({\n            "material": name,\n            "selected_ticker": selected if selected else "MISSING",\n            "candidate_tickers": ", ".join([str(t) for t in ticks if t]),\n            "family": spec.get("family","unknown") if isinstance(spec, dict) else "",\n            "role": spec.get("role","") if isinstance(spec, dict) else "",\n            "proxy_quality": spec.get("proxy_quality","") if isinstance(spec, dict) else "",\n            "weight": spec.get("weight",0.03) if isinstance(spec, dict) else 0.03,\n        })\n    return resolved, pd.DataFrame(rows)\n\ndef zscore(s, window):\n    return (s - s.rolling(window, min_periods=max(5, window//3)).mean()) / s.rolling(window, min_periods=max(5, window//3)).std()\n\ndef build_features(prices, materials, macro, shock_window):\n    resolved, proxy_table = resolve_material_tickers(prices, materials)\n    f = pd.DataFrame(index=prices.index)\n    meta = []\n    for name, ticker in resolved.items():\n        spec = materials.get(name, {})\n        ret = prices[ticker].pct_change(shock_window)\n        col = f"MAT:{name}"\n        f[col] = zscore(ret, max(20, shock_window*4))\n        meta.append({"feature":col, "name":name, "ticker":ticker, "family":spec.get("family","material"), "weight":float(spec.get("weight",0.03)), "role":spec.get("role","")})\n    for name, spec in macro.items():\n        ticker = spec.get("ticker", spec) if isinstance(spec, dict) else spec\n        if ticker in prices.columns:\n            col = f"MACRO:{name}"\n            f[col] = zscore(prices[ticker].pct_change(shock_window), max(20, shock_window*4))\n            meta.append({"feature":col, "name":name, "ticker":ticker, "family":"macro", "weight":0.04, "role":"macro stress"})\n    if f.empty: return f, pd.DataFrame(meta), proxy_table\n    meta_df = pd.DataFrame(meta)\n    weighted, denom = [], 0\n    for _, r in meta_df.iterrows():\n        if r["feature"] in f.columns:\n            w = float(r.get("weight",0.03))\n            weighted.append(f[r["feature"]] * w); denom += w\n    f["GCMSI"] = sum(weighted)/denom if weighted and denom else f.mean(axis=1)\n    for fam in sorted(meta_df["family"].dropna().unique()):\n        cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n        cols = [c for c in cols if c in f.columns]\n        if cols: f[f"FAMILY:{fam}"] = f[cols].mean(axis=1)\n    if "MACRO:VIX" in f.columns:\n        f["REGIME:RiskOff_Materials"] = (f["GCMSI"] + f["MACRO:VIX"]) / 2\n    if "MACRO:USDIndex" in f.columns:\n        f["REGIME:USD_Commodity_Pressure"] = (f["GCMSI"] + f["MACRO:USDIndex"]) / 2\n    return f.replace([np.inf,-np.inf], np.nan).dropna(), meta_df, proxy_table\n\ndef line_chart(df, title, ytitle="Value", normalize=False):\n    if df.empty:\n        st.warning("No data available for chart."); return\n    plot_df = df.copy().dropna(how="all")\n    if normalize:\n        plot_df = plot_df.ffill().dropna(how="all")\n        plot_df = plot_df / plot_df.iloc[0]\n    fig = go.Figure()\n    for col in plot_df.columns:\n        fig.add_trace(go.Scatter(x=plot_df.index, y=plot_df[col], mode="lines", name=str(col), hovertemplate=f"{col}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, xaxis_title="Time", yaxis_title=ytitle, height=430, legend_title="Ticker / Signal", hovermode="x unified")\n    st.plotly_chart(fig, use_container_width=True)\n\ndef bar_chart(series, title):\n    s = series.dropna().sort_values()\n    fig = px.bar(x=s.values, y=s.index, orientation="h", title=title, labels={"x":"Value","y":"Signal"})\n    fig.update_layout(height=max(380, 25*len(s)))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef heatmap(df, title):\n    if df.empty:\n        st.warning("No heatmap data."); return\n    fig = px.imshow(df, aspect="auto", color_continuous_scale="RdBu", zmin=-1, zmax=1, title=title)\n    fig.update_layout(height=520)\n    st.plotly_chart(fig, use_container_width=True)\n\ndef classify(gcmsi, vix, usd, energy, geo_score):\n    if geo_score >= 2.5 and gcmsi > .7: return "Geopolitical materials shock"\n    if gcmsi > 1.5 and vix > 1.0: return "Risk-off industrial stress"\n    if energy > 1.25: return "Energy-cost shock"\n    if usd > 1.0 and gcmsi > .5: return "USD / commodity pressure"\n    if gcmsi > 1.0: return "Commodity stress"\n    if gcmsi < -1.0: return "Stress easing"\n    return "Normal / mixed"\n\ndef stress_state(x):\n    if x >= 2: return "Critical"\n    if x >= 1: return "Elevated"\n    if x <= -1: return "Easing"\n    return "Normal"\n\ndef fwd_return(prices, asset, horizon):\n    return prices[asset].pct_change(horizon).shift(-horizon).rename("future_return")\n\ndef train_one(asset, prices, features, horizon, model_name, feat_cols):\n    if asset not in prices.columns:\n        return None, None, "no downloaded price"\n    y = fwd_return(prices, asset, horizon)\n    df = pd.concat([features[feat_cols], y], axis=1, join="inner").dropna()\n    if len(df) < 90:\n        return None, None, "not enough rows"\n    split = int(len(df)*0.75)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    Xtr, ytr = tr[feat_cols].fillna(0), tr["future_return"].astype(float)\n    Xte, yte = te[feat_cols].fillna(0), te["future_return"].astype(float)\n    model = RandomForestRegressor(n_estimators=250, max_depth=5, random_state=42) if model_name == "RandomForest" else Ridge(alpha=8.0)\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    latest_pred = float(model.predict(features.iloc[[-1]][feat_cols].fillna(0))[0])\n    corr = pd.Series(pred).corr(pd.Series(yte.values)); corr = 0.0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred)**0.5)\n    train_vol = float(ytr.std()) if float(ytr.std()) > 1e-12 else 1.0\n    conf = min(abs(latest_pred) / (train_vol * 1.25), 1.0)\n    direction = "Bullish pressure" if latest_pred > 0 else "Bearish pressure"\n    intensity = "High" if conf > .66 else "Medium" if conf > .33 else "Low"\n    if hasattr(model, "feature_importances_"):\n        imp = pd.Series(model.feature_importances_, index=feat_cols).sort_values(ascending=False)\n    else:\n        imp = pd.Series(np.abs(getattr(model, "coef_", np.zeros(len(feat_cols)))), index=feat_cols).sort_values(ascending=False)\n    te2 = te.copy()\n    te2["prediction"] = pred\n    te2["position"] = np.where(te2["prediction"] > 0, 1.0, -1.0)\n    te2["strategy_return_gross"] = te2["position"] * te2["future_return"]\n    # simple turnover/cost model for usability\n    te2["turnover"] = pd.Series(te2["position"], index=te2.index).diff().abs().fillna(1.0)\n    cost_per_turnover = 0.0005\n    te2["strategy_return_net"] = te2["strategy_return_gross"] - cost_per_turnover * te2["turnover"]\n    te2["equity_net"] = (1 + te2["strategy_return_net"].fillna(0)).cumprod()\n    max_dd = float((te2["equity_net"] / te2["equity_net"].cummax() - 1).min()) if len(te2) else np.nan\n    row = {\n        "asset":asset,\n        "signal":direction,\n        "intensity":intensity,\n        "prediction":latest_pred,\n        "confidence":conf,\n        "test_corr":corr,\n        "rmse":rmse,\n        "max_drawdown_toy":max_dd,\n        "train_rows":len(tr),\n        "test_rows":len(te),\n        "driver_1":imp.index[0] if len(imp)>0 else "",\n        "driver_2":imp.index[1] if len(imp)>1 else "",\n        "driver_3":imp.index[2] if len(imp)>2 else "",\n    }\n    return row, te2, None\n\ndef exposure_adjusted_scores(exposure, latest, geo_score):\n    stress_map = {\n        "copper": latest.get("MAT:Copper",0),\n        "aluminum": latest.get("MAT:Aluminum",0),\n        "nickel": latest.get("MAT:Nickel",0),\n        "steel_chain": latest.get("FAMILY:steel_chain",0),\n        "battery": latest.get("FAMILY:battery_materials",0),\n        "rare_earths": latest.get("FAMILY:critical_minerals",0),\n        "energy": latest.get("FAMILY:energy_inputs",0),\n        "coal": latest.get("MAT:CokingCoal",0) + latest.get("MAT:ThermalCoal",0),\n        "uranium": latest.get("MAT:Uranium",0),\n        "aerospace": latest.get("FAMILY:aerospace_defense_materials",0),\n        "defense": geo_score,\n        "semiconductor": latest.get("FAMILY:electronics_metals",0) + latest.get("FAMILY:critical_minerals",0),\n        "additive_manufacturing": latest.get("GCMSI",0),\n        "china_sensitivity": latest.get("MACRO:USDCNY",0),\n        "geopolitical_sensitivity": geo_score,\n        "macro_beta": latest.get("FAMILY:macro",0),\n    }\n    out = []\n    for _, r in exposure.iterrows():\n        score = 0; denom = 0\n        for k,v in stress_map.items():\n            if k in r and pd.notna(r[k]):\n                score += float(r[k])*float(v)\n                denom += abs(float(r[k]))\n        out.append({"asset":r["asset"], "theme":r.get("theme",""), "region":r.get("region",""), "exposure_adjusted_stress":score/denom if denom else 0})\n    return pd.DataFrame(out).sort_values("exposure_adjusted_stress", ascending=False)\n\n@st.cache_data(ttl=300, show_spinner=False)\ndef gdelt(query, max_records=50):\n    try:\n        url = "https://api.gdeltproject.org/api/v2/doc/doc"\n        params = {"query":query, "mode":"ArtList", "format":"json", "maxrecords":max_records, "sort":"HybridRel"}\n        r = requests.get(url, params=params, timeout=12)\n        if r.status_code != 200: return pd.DataFrame()\n        arts = r.json().get("articles", [])\n        return pd.DataFrame([{"title":a.get("title",""),"domain":a.get("domain",""),"source_country":a.get("sourceCountry",""),"date":a.get("seendate",""),"url":a.get("url","")} for a in arts])\n    except Exception:\n        return pd.DataFrame()\n\ndef geo_score(news, geo_cfg):\n    if news.empty:\n        return 0.0, pd.DataFrame()\n    titles = " ".join(news["title"].fillna("").astype(str)).lower()\n    rows = []; score = 0\n    for theme, spec in geo_cfg.get("themes", {}).items():\n        if isinstance(spec, dict):\n            words = spec.get("words", []); weight = float(spec.get("weight", 1))\n        else:\n            words = spec; weight = 1\n        count = sum(titles.count(str(w).lower()) for w in words)\n        score += count * weight\n        rows.append({"theme":theme, "mentions":count, "weighted_score":count*weight})\n    score = min(score/12, 4.0)\n    return score, pd.DataFrame(rows).sort_values("weighted_score", ascending=False)\n\ndef recommendation_text(row):\n    if row["confidence"] < .25:\n        return "Observe only: weak model conviction."\n    if row["signal"].startswith("Bullish"):\n        return "Research watch: positive pressure; check drivers and validation before trusting."\n    return "Risk watch: negative pressure; check exposure and geopolitical/macro context."\n\n# ---------------- UI ----------------\nst.set_page_config(page_title="MatQuantLab V5 Pro", layout="wide")\nst.title("MatQuantLab V5 — Pro Critical Materials Intelligence")\nst.caption("Labeled interactive charts, expanded material proxies, geopolitical risk, exposure-aware prediction table, and faster refresh. Research only.")\n\nidx_df = flatten_indices(indices_cfg)\nmacro_tickers = {k:(v.get("ticker",v) if isinstance(v,dict) else v) for k,v in macro_cfg.items()}\nall_assets = sorted(set(exposure["asset"].astype(str).tolist() + ["XME","COPX","PICK","XLB","ITA","XAR","XLI","VIS","PRNT","DDD","SSYS","MTLS","NNDM","SOXX","SPY","EEM","URTH","MXI","EXI","XLE","URA","LIT","REMX","SLX"]))\ndefault_assets = [a for a in ["XME","COPX","ITA","XAR","PRNT","SOXX","URA","LIT","REMX","SPY","EEM"] if a in all_assets]\n\nwith st.sidebar:\n    st.header("Controls")\n    selected_assets = st.multiselect("Assets to predict", all_assets, default=default_assets)\n    interval = st.selectbox("Refresh/data interval", ["1m","5m","15m","30m","60m","1d"], index=1)\n    period = st.selectbox("Lookback period", ["1d","5d","1mo","3mo","6mo","1y"], index=1)\n    model_name = st.selectbox("Model", ["Ridge","RandomForest"], index=0)\n    horizon = st.slider("Prediction horizon in bars", 1, 120, 12)\n    shock_window = st.slider("Shock window in bars", 3, 100, 20)\n    max_news = st.slider("News items", 10, 80, 40)\n    news_query = st.text_area("Geopolitical query", value=geo_cfg.get("default_query","critical minerals OR rare earth OR sanctions"), height=90)\n    auto = st.toggle("Auto-refresh app", value=False)\n    refresh_seconds = st.selectbox("Auto-refresh seconds", [30,60,120,300], index=1)\n    if st.button("Force refresh now"):\n        st.cache_data.clear(); st.rerun()\n\nif auto:\n    time.sleep(refresh_seconds)\n    st.cache_data.clear()\n    st.rerun()\n\nperiod = safe_period(interval, period)\n\ncandidate_material_tickers = all_candidate_tickers_for_materials(materials_cfg)\ntickers = sorted(set(selected_assets + candidate_material_tickers + list(macro_tickers.values()) + idx_df["ticker"].dropna().tolist()))\nprices = download_prices(tickers, period, interval)\nif prices.empty:\n    st.error("No prices downloaded. Try 5m/5d or 1d/1y.")\n    st.stop()\n\nfeatures, meta, proxy_table = build_features(prices, materials_cfg, macro_tickers, shock_window)\nif features.empty:\n    st.error("No features built. Try longer period or daily interval.")\n    st.stop()\n\nnews = gdelt(news_query, max_records=max_news)\ngscore, gthemes = geo_score(news, geo_cfg)\nlatest = features.iloc[-1]\nregime = classify(latest.get("GCMSI",0), latest.get("MACRO:VIX",0), latest.get("MACRO:USDIndex",0), latest.get("FAMILY:energy_inputs",0), gscore)\nstate = stress_state(float(latest.get("GCMSI",0)))\n\nfeat_cols = [c for c in features.columns if c.startswith("MAT:") or c.startswith("MACRO:") or c.startswith("FAMILY:") or c.startswith("REGIME:") or c=="GCMSI"]\npred_rows = []; curves = {}\nfor a in selected_assets:\n    row, curve, err = train_one(a, prices, features, horizon, model_name, feat_cols)\n    if row:\n        row["risk_action"] = recommendation_text(row)\n        exp = exposure.loc[exposure["asset"].astype(str)==a]\n        if len(exp):\n            row["theme"] = exp.iloc[0].get("theme","")\n            row["region"] = exp.iloc[0].get("region","")\n        pred_rows.append(row); curves[a] = curve\npred = pd.DataFrame(pred_rows)\nif not pred.empty:\n    pred = pred.sort_values(["confidence","test_corr"], ascending=[False, False])\n\nk1,k2,k3,k4,k5,k6 = st.columns(6)\nk1.metric("GCMSI", f"{latest.get(\'GCMSI\',0):.2f}")\nk2.metric("Stress state", state)\nk3.metric("Regime", regime)\nk4.metric("Geo score", f"{gscore:.2f}")\nk5.metric("Downloaded tickers", prices.shape[1])\nk6.metric("Predicted assets", len(pred))\nst.info("Message: MatQuantLab is an industrial stress radar, not a stock-prediction toy. It links material proxies, macro shocks, geopolitical news, and exposure scores to explain risk pressure.")\n\ntabs = st.tabs(["Pro Radar","Prediction Table","Ticker Charts","Material Universe","Exposure Matrix","Geo Risk News","Global Indices","Validation","Raw Data"])\n\nwith tabs[0]:\n    st.subheader("Pro Radar — labeled interactive stress charts")\n    radar_cols = [c for c in ["GCMSI","FAMILY:industrial_metals","FAMILY:steel_chain","FAMILY:battery_materials","FAMILY:critical_minerals","FAMILY:aerospace_defense_materials","FAMILY:energy_inputs","FAMILY:macro"] if c in features.columns]\n    line_chart(features[radar_cols], "Global Critical Materials Stress Dashboard", "Z-score / stress", normalize=False)\n    drivers = latest[[c for c in features.columns if c.startswith("MAT:") or c.startswith("MACRO:")]].sort_values(key=lambda s: s.abs(), ascending=False).head(20)\n    bar_chart(drivers, "Top 20 Current Stress Drivers")\n    st.markdown("### What to read")\n    st.write("- **GCMSI up** = global material/macro stress is rising.")\n    st.write("- **Energy + aerospace stress** = possible margin pressure for aerospace/industrial supply chain.")\n    st.write("- **Critical minerals + geopolitical score up** = export-control / defense / battery-chain risk.")\n\nwith tabs[1]:\n    st.subheader("Prediction Table — usable signal summary")\n    if pred.empty:\n        st.warning("No predictions. Try longer period, daily interval, or fewer assets.")\n    else:\n        cols = ["asset","theme","region","signal","intensity","prediction","confidence","test_corr","rmse","max_drawdown_toy","driver_1","driver_2","driver_3","risk_action"]\n        st.dataframe(pred[cols], use_container_width=True)\n        chosen = st.selectbox("Deep explanation", pred["asset"].tolist())\n        row = pred[pred["asset"]==chosen].iloc[0]\n        st.markdown(f"### {chosen}: {row[\'signal\']} / {row[\'intensity\']} confidence")\n        st.write(f"**Prediction:** {row[\'prediction\']:.5f}")\n        st.write(f"**Confidence:** {row[\'confidence\']:.2f}")\n        st.write(f"**Validation correlation:** {row[\'test_corr\']:.3f}")\n        st.write(f"**Main drivers:** `{row[\'driver_1\']}`, `{row[\'driver_2\']}`, `{row[\'driver_3\']}`")\n        st.write(f"**Interpretation:** {row[\'risk_action\']}")\n        if chosen in curves:\n            line_chart(curves[chosen][["prediction","future_return"]], f"{chosen} prediction vs future return", "Return")\n            line_chart(curves[chosen][["equity_net"]], f"{chosen} toy net equity curve", "Equity")\n\nwith tabs[2]:\n    st.subheader("Ticker Charts — every line has ticker labels")\n    tick_choices = st.multiselect("Tickers to chart", list(prices.columns), default=[t for t in selected_assets if t in prices.columns][:8])\n    if tick_choices:\n        line_chart(prices[tick_choices], "Normalized selected ticker prices", "Normalized price", normalize=True)\n        line_chart(prices[tick_choices], "Raw selected ticker prices", "Price", normalize=False)\n\nwith tabs[3]:\n    st.subheader("Material Universe and Available Proxies")\n    st.write("Each material can have multiple possible public-market proxies. The app automatically uses the first one successfully downloaded.")\n    st.dataframe(proxy_table, use_container_width=True)\n    available = proxy_table[proxy_table["selected_ticker"]!="MISSING"]\n    missing = proxy_table[proxy_table["selected_ticker"]=="MISSING"]\n    c1,c2 = st.columns(2)\n    c1.metric("Materials available", len(available))\n    c2.metric("Materials missing", len(missing))\n    if len(available):\n        mat_cols = [f"MAT:{m}" for m in available["material"] if f"MAT:{m}" in features.columns]\n        line_chart(features[mat_cols[:15]], "Available material shock signals", "Z-score")\n\nwith tabs[4]:\n    st.subheader("Exposure Matrix — material logic behind assets")\n    st.dataframe(exposure, use_container_width=True)\n    score_df = exposure_adjusted_scores(exposure, latest, gscore)\n    st.markdown("### Exposure-adjusted stress ranking")\n    st.dataframe(score_df, use_container_width=True)\n    fig = px.bar(score_df, x="exposure_adjusted_stress", y="asset", color="theme", orientation="h", title="Exposure-adjusted stress by asset")\n    fig.update_layout(height=550)\n    st.plotly_chart(fig, use_container_width=True)\n\nwith tabs[5]:\n    st.subheader("Geopolitical Materials News — stronger risk scan")\n    state_geo = "Critical" if gscore>=3 else "High" if gscore>=2 else "Elevated" if gscore>=.8 else "Normal"\n    st.metric("Geopolitical Materials Risk", state_geo, f"{gscore:.2f}")\n    if not gthemes.empty:\n        st.dataframe(gthemes, use_container_width=True)\n        fig = px.bar(gthemes, x="weighted_score", y="theme", orientation="h", title="Geopolitical theme intensity")\n        st.plotly_chart(fig, use_container_width=True)\n    if news.empty:\n        st.warning("No GDELT news returned. Try a simpler query.")\n    else:\n        for _, r in news.head(max_news).iterrows():\n            st.markdown(f"**{r[\'title\']}**  \\n`{r.get(\'domain\',\'\')}` | `{r.get(\'source_country\',\'\')}` | `{r.get(\'date\',\'\')}`  \\n{r[\'url\']}")\n\nwith tabs[6]:\n    st.subheader("Global Indices — US / Europe / China / Japan / Global")\n    region = st.selectbox("Region", sorted(idx_df["region"].unique()) if not idx_df.empty else [])\n    if region:\n        tickers_region = idx_df[idx_df["region"]==region]["ticker"].tolist()\n        tickers_region = [t for t in tickers_region if t in prices.columns]\n        if tickers_region:\n            line_chart(prices[tickers_region], f"{region} normalized indices", "Normalized", normalize=True)\n            recent = []\n            for t in tickers_region:\n                ret = prices[t].pct_change(min(20, max(1, len(prices)//5))).dropna()\n                recent.append({"ticker":t, "recent_return":float(ret.iloc[-1]) if len(ret) else np.nan})\n            st.dataframe(pd.DataFrame(recent).sort_values("recent_return", ascending=False), use_container_width=True)\n        else:\n            st.warning("No tickers downloaded for this region.")\n\nwith tabs[7]:\n    st.subheader("Validation / ranking")\n    if pred.empty:\n        st.warning("No validation.")\n    else:\n        st.dataframe(pred[["asset","test_corr","rmse","max_drawdown_toy","train_rows","test_rows","confidence","intensity"]], use_container_width=True)\n        metric = st.selectbox("Sort chart metric", ["confidence","test_corr","rmse","max_drawdown_toy"])\n        s = pred.set_index("asset")[metric].sort_values()\n        bar_chart(s, f"Assets ranked by {metric}")\n        st.caption("Still research-only: validation is a simple chronological split with a toy cost model. This is better than random split but not institutional yet.")\n\nwith tabs[8]:\n    st.subheader("Downloaded prices")\n    st.dataframe(prices.tail(60), use_container_width=True)\n    st.subheader("Features")\n    st.dataframe(features.tail(60), use_container_width=True)\n    st.subheader("Feature metadata")\n    st.dataframe(meta, use_container_width=True)\n\nst.divider()\nst.caption("Data: Yahoo Finance via yfinance + GDELT news. Free data may be delayed/incomplete. Not financial advice.")\n')
